<?php
 namespace Pterodactyl\Notifications; use Pterodactyl\Models\User; use Illuminate\Bus\Queueable; use Pterodactyl\Services\Dezerx\Emails; use Illuminate\Notifications\Notification; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Notifications\Messages\MailMessage; class AccountCreated extends Notification implements ShouldQueue { use Queueable; public function __construct(public User $user, public ?string $token = null) { } public function via(): array { return ['mail']; } public function toMail(): MailMessage { return Emails::apply(new MailMessage(), 'account-created', [ 'name' => $this->user->name, 'username' => $this->user->username, 'email' => $this->user->email, ], is_null($this->token) ? '' : url('/auth/password/reset/' . $this->token . '?email=' . urlencode($this->user->email))); } } 